#include "GameApplicationComposition.hpp"
namespace th143 {
bool GameApplicationComposition::read_render_memory(u32 p,void* out,u32 n){if(p>=0x4e47d0&&std::uint64_t(p)+n<=std::uint64_t(0x4e47d0)+render.application.size()){std::memcpy(out,render.application.data()+p-0x4e47d0,n);return true;}return targets.read_render_memory(p,out,n)||device.read_game_render_memory(p,out,n);}
bool GameApplicationComposition::write_render_memory(u32 p,const void* in,u32 n){if(p>=0x4e47d0&&std::uint64_t(p)+n<=std::uint64_t(0x4e47d0)+render.application.size()){std::memcpy(render.application.data()+p-0x4e47d0,in,n);return true;}return targets.write_render_memory(p,in,n)||device.write_game_render_memory(p,in,n);}
void GameApplicationComposition::synchronize_render_state(){auto app=AnmView{render.application.data()};render.drawing.camera_token=app.get(0x6e0);render.drawing.camera_kind=app.get(0x6e4);render.drawing.depth_write=app.get(0xa00);render.drawing.depth_test=render.depth_test=app.get(0xa04);}
bool GameApplicationComposition::composition_render_state(u32 p,u32 state,u32 value){synchronize_render_state();return p==device.game_device_token()&&device.render_state(state,value);}
bool GameApplicationComposition::draw_composition_animation(u32 manager,u32 token){if(manager!=0x72000000)return false;synchronize_render_state();auto vm=targets.target_animation(token);return vm.data&&render.draw_player_visual(token,vm);}
bool GameApplicationComposition::draw_composition_layer(u32 manager,u32 layer){if(manager!=0x72000000||layer!=33)return false;synchronize_render_state();u32 token;if(!world.read(manager+0xfe87b8+layer*0x5cc,&token,4))return false;for(u32 budget=0;token;){if(++budget>1000000)return false;auto vm=world.state(token);if(!vm.data)return false;if(!(vm.get(0x1c)&0x20)&&!render.draw_player_visual(token,vm))return false;token=vm.get(0x590);}return true;}
bool GameApplicationComposition::reset_batches(){return world.pool&&world.pool->self==0x72000000&&initialize_anm_batches(0x72000000,*this);}
bool GameApplicationComposition::begin_frame(ApplicationFrameGlobals& g,bool reset){if(!world.pool||world.pool->self!=0x72000000)return false;render.submitted=render.error=0;if((reset&&!reset_batches())||!begin_application_frame({render.application.data()},0x4e47d0,0x72000000,g,*this,device,device))return false;world.viewport.first_origin=g.first_origin;synchronize_render_state();return true;}
bool GameApplicationComposition::draw(ApplicationCompositionPass pass,ApplicationCompositionGlobals& g){if(!world.pool||world.pool->self!=0x72000000)return false;const bool ok=compose_application({render.application.data()},0x4e47d0,0x72000000,pass,g,*this,device,device,*this);synchronize_render_state();return ok;}
}
